package com.matthayesego.duckforcetoolkit;

import android.app.Activity;
import android.content.Intent;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.view.Gravity;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;

/** Password-authorized front door for hidden developer tools. */
public class DeveloperPanelActivity extends Activity {
    private static final int BG=Color.rgb(6,9,13),PANEL=Color.rgb(15,20,28),BORDER=Color.rgb(45,55,69),TEXT=Color.rgb(244,246,249),MUTED=Color.rgb(154,164,178),GOLD=Color.rgb(241,194,106),BLUE=Color.rgb(88,166,255),GREEN=Color.rgb(63,185,80);
    private int factionId;private String factionName;private boolean factionApi;private String position;
    @Override protected void onCreate(Bundle savedInstanceState){super.onCreate(savedInstanceState);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);factionId=getIntent().getIntExtra(DeveloperConsoleActivity.EXTRA_FACTION_ID,0);factionName=getIntent().getStringExtra(DeveloperConsoleActivity.EXTRA_FACTION_NAME);factionApi=getIntent().getBooleanExtra(DeveloperConsoleActivity.EXTRA_FACTION_API,false);position=getIntent().getStringExtra(DeveloperConsoleActivity.EXTRA_POSITION);if(factionName==null||factionName.trim().isEmpty())factionName="No faction context";if(position==null||position.trim().isEmpty())position="Unknown role";render();}
    private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
    private GradientDrawable rounded(int fill,int stroke,int radius){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));if(stroke!=Color.TRANSPARENT)d.setStroke(dp(1),stroke);return d;}
    private TextView text(String value,float size,int color,boolean bold){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
    private Button button(String label,int stroke){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(TEXT);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setBackground(rounded(PANEL,stroke,12));return b;}
    private LinearLayout card(String title,String body,int stroke){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(17),dp(16),dp(17),dp(16));c.setBackground(rounded(PANEL,stroke,17));c.addView(text(title,19,TEXT,true));TextView b=text(body,13,MUTED,false);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);p.topMargin=dp(6);c.addView(b,p);return c;}
    private void addCard(LinearLayout r,LinearLayout c){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);p.bottomMargin=dp(10);r.addView(c,p);}
    @SuppressWarnings("deprecation") private ScrollView shell(){ScrollView s=new ScrollView(this);s.setFillViewport(true);s.setBackgroundColor(BG);int l=dp(16),t=dp(20),r=dp(16),b=dp(28);s.setPadding(l,t,r,b);s.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(l+i.getSystemWindowInsetLeft(),t+i.getSystemWindowInsetTop(),r+i.getSystemWindowInsetRight(),b+i.getSystemWindowInsetBottom());return i;});return s;}
    private void render(){ScrollView s=shell();LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);s.addView(r,new ScrollView.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));Button back=button("← Companion",BORDER);back.setOnClickListener(v->finish());r.addView(back,new LinearLayout.LayoutParams(dp(132),dp(44)));TextView brand=text("DUCK FORCE • HIDDEN DEVELOPER CHANNEL",10,GOLD,true);brand.setLetterSpacing(.10f);brand.setGravity(Gravity.CENTER);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);bp.topMargin=dp(18);r.addView(brand,bp);TextView title=text("Developer Panel",30,TEXT,true);title.setGravity(Gravity.CENTER);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);tp.topMargin=dp(5);tp.bottomMargin=dp(4);r.addView(title,tp);TextView sub=text(factionName+" • "+position+" • password-authorized",13,MUTED,false);sub.setGravity(Gravity.CENTER);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);sp.bottomMargin=dp(18);r.addView(sub,sp);boolean preview=DeveloperPreviewStore.isMemberPreview(this);LinearLayout previewCard=card("Standard Member Preview",preview?"ACTIVE — the Companion is presenting the non-leadership member view. Your actual Torn identity and backend permissions are unchanged.":"Switch the presentation layer to what a normal non-leadership faction member sees, without impersonating another player or changing server authorization.",preview?GREEN:GOLD);Button toggle=button(preview?"Exit Member Preview":"Enter Member Preview",preview?GREEN:GOLD);toggle.setOnClickListener(v->{DeveloperPreviewStore.setMemberPreview(this,!DeveloperPreviewStore.isMemberPreview(this));Intent i=new Intent(this,V095CompanionActivity.class);startActivity(i);finish();});LinearLayout.LayoutParams tgp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(48));tgp.topMargin=dp(12);previewCard.addView(toggle,tgp);addCard(r,previewCard);LinearLayout advanced=card("Advanced Developer Console","Open diagnostics, permission simulation, feature switches, faction-scope cache controls and other existing developer tools.",BLUE);Button open=button("Open Advanced Console",BLUE);open.setOnClickListener(v->{Intent i=new Intent(this,DeveloperConsoleActivity.class);i.putExtra(DeveloperConsoleActivity.EXTRA_FACTION_ID,factionId);i.putExtra(DeveloperConsoleActivity.EXTRA_FACTION_NAME,factionName);i.putExtra(DeveloperConsoleActivity.EXTRA_FACTION_API,factionApi);i.putExtra(DeveloperConsoleActivity.EXTRA_POSITION,position);startActivity(i);});LinearLayout.LayoutParams op=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(48));op.topMargin=dp(12);advanced.addView(open,op);addCard(r,advanced);addCard(r,card("Safety boundary","Member Preview is visual/local only. It never rewrites player_id, faction_id, Torn permissions, banking authorization or server-side access checks.",BORDER));TextView footer=text("Duck Force Companion v0.9.7 • hidden developer channel",11,MUTED,false);footer.setGravity(Gravity.CENTER);LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);fp.topMargin=dp(8);r.addView(footer,fp);setContentView(s);s.requestApplyInsets();}
}
